'use client';

/**
 * Translations for @kortix/ui components. A host passes its own hooks through
 * `<UiProvider i18n>` (apps/web passes its next-intl hooks). Without them,
 * components translate from `locale` + `messages`, else from the bundled
 * English catalog `en.ts` (generated by scripts/gen-i18n-catalog.mjs).
 */
import * as React from 'react';
import {
  createTranslator,
  type AbstractIntlMessages,
  type useTranslations as useIntlTranslations,
} from 'use-intl';

import { useUiI18nHost } from '../providers/ui-provider';
import catalog from './en';

/** The bundled English catalog: every namespace @kortix/ui components read. */
export type UiMessages = typeof catalog;
export const defaultUiMessages: UiMessages = catalog;

/** The `useTranslations` signature of use-intl and next-intl. */
export type UiUseTranslations = typeof useIntlTranslations;

/** A translator for `hardcodedUi.i18nComplete`, typed against the bundled catalog. */
export type UiTranslator = ReturnType<
  typeof createTranslator<UiMessages, 'hardcodedUi.i18nComplete'>
>;

/** use-intl's framework-free translator, for a host that types its own catalog. */
export { createTranslator };

/** What a host passes as `<UiProvider i18n>` (defined beside the provider). */
export type { UiI18nHost } from '../providers/ui-provider';

function useCatalogTranslations(namespace?: string) {
  const host = useUiI18nHost();
  const locale = host?.locale ?? 'en';
  const messages = host?.messages ?? (defaultUiMessages as AbstractIntlMessages);
  return React.useMemo(
    () => createTranslator({ locale, messages, namespace: namespace as never }),
    [locale, messages, namespace],
  );
}

/** next-intl's `useTranslations`: `t(key, values)`, `t.rich`, `t.markup`, `t.raw`, `t.has`. */
export const useTranslations = ((namespace?: string) => {
  const useHost = useUiI18nHost()?.useTranslations as ((ns?: string) => unknown) | undefined;
  return (useHost ?? useCatalogTranslations)(namespace);
}) as UiUseTranslations;

export function useLocale(): string {
  const host = useUiI18nHost();
  const useHost = host?.useLocale;
  // The host object is stable (see UiI18nHost), so the branch never flips between renders.
  // eslint-disable-next-line react-hooks/rules-of-hooks
  return useHost ? useHost() : (host?.locale ?? 'en');
}
export { localizeUiCatalog, translateUiCatalogText } from './ui-catalog/localize-ui-catalog';
export { useLocalizedUiCatalog } from './ui-catalog/use-localized-ui-catalog';
